# 工作流API端点
WORKFLOW_API_URL = "https://api.coze.cn/v1/workflow/run"


async def call_workflow(workflow_name: str, payload: Dict[str, Any]) -> Dict[str, Any]:
    """
    调用扣子工作流

    Args:
        workflow_name: 工作流名称（如 script-generate）
        payload: 请求参数

    Returns:
        工作流执行结果
    """
    token = WORKFLOW_TOKENS.get(workflow_name)
    if not token:
        raise ValueError(f"未知工作流: {workflow_name}")

    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
    }

    async with httpx.AsyncClient(timeout=120.0) as client:
        response = await client.post(
            WORKFLOW_API_URL,
            headers=headers,
            json=payload,
        )
        response.raise_for_status()
        return await response.json()
